// daily-data.js — the content the homepage "For today" feed draws from.
// Each array is picked deterministically by the day number, so the same item
// shows all day and cycles with Shuffle. Add freely; keep sources honest.
//
//   QUOTES    — a single line from a master builder or critic (the hero card)
//   THOUGHTS  — a short paragraph to turn over during the day
//   VERSES    — a "rule of good building" to hold in memory
//   PASSAGES  — a longer excerpt from a great work on architecture, to read slowly
//   WORDS     — a term of the craft, its origin and where to see it
//
// The "one thing to notice today" card is built from the practice lists in
// elements-data.js / styles-data.js, so it needs no data here.

window.QUOTES = [
  { text: 'Well building hath three conditions: firmness, commodity, and delight.', author: 'Sir Henry Wotton', source: 'The Elements of Architecture, 1624 (after Vitruvius)' },
  { text: 'Architecture aims at eternity.', author: 'Sir Christopher Wren', source: 'Parentalia' },
  { text: 'Beauty will result from the form and correspondence of the whole, with respect to the several parts, of the parts with regard to each other, and of these again to the whole.', author: 'Andrea Palladio', source: 'The Four Books of Architecture, 1570' },
  { text: 'Ornament is and should be the expression of love, and it should be tender.', author: 'John Ruskin', source: 'The Seven Lamps of Architecture, 1849' },
  { text: 'The architect should be equipped with knowledge of many branches of study — for it is by his judgement that all work done by the other arts is put to test.', author: 'Vitruvius', source: 'De Architectura, Book I' },
  { text: 'No architecture is so haughty as that which is simple.', author: 'John Ruskin', source: 'The Stones of Venice' },
  { text: 'The orders are to the architect what the letters of the alphabet are to the writer.', author: 'John Summerson', source: 'The Classical Language of Architecture, 1963' },
  { text: 'That is beautiful which pleases when seen — id pulchrum quod visum placet.', author: 'Thomas Aquinas', source: 'in the medieval tradition of proportion' },
  { text: 'Proportion is that agreeable harmony between the several parts of a building.', author: 'Vitruvius', source: 'De Architectura, Book I' },
  { text: 'When we build, let us think that we build for ever.', author: 'John Ruskin', source: 'The Seven Lamps of Architecture, 1849 (the Lamp of Memory)' },
  { text: 'You must either make a tool of the creature, or a man of him. You cannot make both.', author: 'John Ruskin', source: '"The Nature of Gothic", The Stones of Venice, 1853' },
  { text: 'Form ever follows function.', author: 'Louis Sullivan', source: '"The Tall Office Building Artistically Considered", 1896 — meant as a spiritual law, not cold utility' },
  { text: 'Architecture is the masterly, correct and magnificent play of masses brought together in light.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923' },
  { text: 'You say to a brick, "What do you want, brick?" And brick says, "I like an arch."', author: 'Louis Kahn', source: 'talks with students, 1969' },
  { text: 'I sense Light as the giver of all presences.', author: 'Louis Kahn', source: 'in Patricia Cummings Loud, The Art Museums of Louis I. Kahn, 1989' },
  { text: 'The best of artists hath no thought to show which the rough stone in its superfluous shell doth not include.', author: 'Michelangelo', source: 'sonnet, "Non ha l’ottimo artista"' },
  { text: 'Consult the Genius of the Place in all.', author: 'Alexander Pope', source: 'Epistle to Lord Burlington, 1731' },
  { text: 'No work can be rightly done without honesty and incorruptibility.', author: 'Vitruvius', source: 'De Architectura, Book I, ch. 1 (Morgan trans.)' },
  { text: 'Beauty is that reasoned harmony of all the parts within a body, so that nothing may be added, taken away, or altered, but for the worse.', author: 'Leon Battista Alberti', source: 'On the Art of Building, Book VI, c. 1450 (Rykwert/Leach/Tavernor trans.)' },
  { text: 'Lector, si monumentum requiris, circumspice — Reader, if you seek his monument, look around you.', author: 'epitaph of Sir Christopher Wren, St Paul\'s Cathedral', source: 'composed by his son, Christopher Wren the Younger' },
  { text: 'We shape our buildings, and afterwards our buildings shape us.', author: 'Winston Churchill', source: 'House of Commons, 28 October 1943, on rebuilding the bombed Commons chamber (Hansard wording; often paraphrased "thereafter they shape us")' },
  { text: 'A house is a machine for living in.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923' },
  { text: 'Form and function are one.', author: 'Frank Lloyd Wright', source: 'A Testament, 1957' },
  { text: 'The passion caused by the great and sublime is astonishment; and astonishment is that state of the soul in which all its motions are suspended.', author: 'Edmund Burke', source: 'A Philosophical Enquiry into the Sublime and Beautiful, 1757' },
  { text: 'Design is the father of our three arts — architecture, sculpture and painting — having its origin in the intellect.', author: 'Giorgio Vasari', source: 'Lives of the Artists, 1550' },
  { text: 'First delight, then instruct.', author: 'Karl Friedrich Schinkel', source: 'memorandum on the Altes Museum, Berlin, 1828 (with Gustav Waagen)' },
  { text: 'Indifference to the fine arts comes close to barbarism.', author: 'Karl Friedrich Schinkel', source: 'recorded aphorism' },
  { text: 'There should be no features about a building which are not necessary for convenience, construction, or propriety.', author: 'A. W. N. Pugin', source: 'The True Principles of Pointed or Christian Architecture, 1841' },
  { text: 'The demand for perfection is always a sign of a misunderstanding of the ends of art.', author: 'John Ruskin', source: '"The Nature of Gothic", The Stones of Venice, 1853' },
  { text: 'In imitating the model well, it is sometimes necessary to introduce into a marble portrait something that is not found in the model.', author: 'Gian Lorenzo Bernini', source: 'recorded in Chantelou\'s Diary of Bernini\'s Visit to France, 1665' },
  { text: 'A great building must begin with the unmeasurable, must go through measurable means when it is being designed, and in the end must be unmeasurable.', author: 'Louis Kahn', source: 'writings and lectures' },
  { text: 'Beauty matters; it is not just a subjective thing but a universal need of human beings.', author: 'Sir Roger Scruton', source: 'Why Beauty Matters, BBC, 2009' },
  { text: 'There is one timeless way of building. It is thousands of years old, and the same today as it has always been.', author: 'Christopher Alexander', source: 'The Timeless Way of Building, 1979' },
  { text: 'Him I call an architect, who is able, with thought and invention, to devise, and with execution to complete, all those works which can most beautifully be fitted out for the noble needs of man.', author: 'Leon Battista Alberti', source: 'On the Art of Building, Prologue, c. 1452' },
  { text: 'Let us never forget that all the magnificence of architecture derives from the simple hut.', author: 'Marc-Antoine Laugier', source: 'Essay on Architecture, 1753' },
  { text: 'Where there is no reason, there should be no column, no pilaster, no arch.', author: 'Marc-Antoine Laugier', source: 'Essay on Architecture, 1753' },
  { text: 'What is architecture? Shall I define it with Vitruvius as the art of building? No. One must conceive in order to execute.', author: 'Etienne-Louis Boullee', source: 'Architecture, essai sur l’art, c. 1790' },
  { text: 'To build is to create; to create characters is to give buildings a soul.', author: 'Claude-Nicolas Ledoux', source: 'L’Architecture, 1804' },
  { text: 'Noble simplicity and calm grandeur are the true mark of the excellence of Greek works.', author: 'Johann Joachim Winckelmann', source: 'Reflections on the Imitation of Greek Works, 1755' },
  { text: 'The only way for us to become great is by the imitation of the ancients.', author: 'Johann Joachim Winckelmann', source: 'Reflections on the Imitation of Greek Works, 1755' },
  { text: 'Architecture so disposes and adorns the edifices raised by man that the sight of them contributes to his mental health, power, and pleasure.', author: 'John Ruskin', source: 'The Seven Lamps of Architecture, 1849' },
  { text: 'The greatest glory of a building is not in its stones, nor in its gold. Its glory is in its Age.', author: 'John Ruskin', source: 'The Seven Lamps of Architecture, the Lamp of Memory, 1849' },
  { text: 'No architecture can be truly noble which is not imperfect.', author: 'John Ruskin', source: 'The Stones of Venice, 1853' },
  { text: 'Better the rudest work that tells a story or records a fact, than the richest without meaning.', author: 'John Ruskin', source: 'The Seven Lamps of Architecture, 1849' },
  { text: 'Every building, to be perfectly beautiful, must exactly express the wants that gave it birth.', author: 'Eugene Viollet-le-Duc', source: 'Lectures on Architecture, 1863' },
  { text: 'Have nothing in your houses that you do not know to be useful, or believe to be beautiful.', author: 'William Morris', source: 'The Beauty of Life, lecture, 1880' },
  { text: 'The true and only source and mother of ornament is nature.', author: 'Owen Jones', source: 'The Grammar of Ornament, 1856' },
  { text: 'The evolution of culture marches with the elimination of ornament from useful objects.', author: 'Adolf Loos', source: 'Ornament and Crime, lecture 1910' },
  { text: 'If we find a mound in the woods, six feet long and three feet wide, raised to a pyramid, we grow serious, and something says: someone lies buried here. That is architecture.', author: 'Adolf Loos', source: 'Architecture, essay, 1910' },
  { text: 'Architecture studies not structure in itself, but the effect of structure on the human spirit.', author: 'Geoffrey Scott', source: 'The Architecture of Humanism, 1914' },
  { text: 'No house should ever be on a hill. It should be of the hill, belonging to it, so that hill and house may live together, each the happier for the other.', author: 'Frank Lloyd Wright', source: 'An Autobiography, 1932' },
  { text: 'A doctor can bury his mistakes, but an architect can only advise his client to plant vines.', author: 'Frank Lloyd Wright', source: 'New York Times Magazine, 1953' },
  { text: 'Study nature, love nature, stay close to nature. It will never fail you.', author: 'Frank Lloyd Wright', source: 'to the Taliesin Fellowship, c. 1955' },
  { text: 'Space is the breath of art.', author: 'Frank Lloyd Wright', source: 'The Future of Architecture, 1953' },
  { text: 'The mother art is architecture. Without an architecture of our own, we have no soul of our own civilization.', author: 'Frank Lloyd Wright', source: 'An Autobiography, 1932' },
  { text: 'God created paper for the purpose of drawing architecture on it. Everything else is an abuse of paper.', author: 'Alvar Aalto', source: 'sketchbook note, quoted by Goran Schildt' },
  { text: 'Any architecture that does not express serenity is a mistake.', author: 'Luis Barragan', source: 'Pritzker Prize address, 1980' },
  { text: 'I believe in an emotional architecture. It is very important for humankind that architecture should move us by its beauty.', author: 'Luis Barragan', source: 'Pritzker Prize address, 1980' },
  { text: 'Silence, solitude, serenity: these are values that have accompanied me throughout my life.', author: 'Luis Barragan', source: 'Pritzker Prize address, 1980' },
  { text: 'I want to see, and that is why I draw. I can see an image only if I draw it.', author: 'Carlo Scarpa', source: 'lecture, Can Architecture Be Poetry?, 1976' },
  { text: 'I consider light not so much a physical quantity as a bearer of meaning.', author: 'Peter Zumthor', source: 'Atmospheres, 2006' },
  { text: 'Details, when they are successful, are not mere decoration; they lead to an understanding of the whole of which they are a part.', author: 'Peter Zumthor', source: 'Thinking Architecture, 1998' },
  { text: 'If you make bad architecture, you impose ugliness on a place for a hundred years.', author: 'Renzo Piano', source: 'interview, 2001' },
  { text: 'Cities have the capability of providing something for everybody, only because, and only when, they are created by everybody.', author: 'Jane Jacobs', source: 'The Death and Life of Great American Cities, 1961' },
  { text: 'We must stop treating the city plan as an abstract chessboard, and remember that it is a work of art.', author: 'Camillo Sitte', source: 'City Planning According to Artistic Principles, 1889' },
  { text: 'The city is the locus of the collective memory of its people.', author: 'Aldo Rossi', source: 'The Architecture of the City, 1966' },
  { text: 'Less is a bore.', author: 'Robert Venturi', source: 'Complexity and Contradiction in Architecture, 1966' },
  { text: 'I am for messy vitality over obvious unity.', author: 'Robert Venturi', source: 'Complexity and Contradiction in Architecture, 1966' },
  { text: 'Architecture is the will of an epoch translated into space.', author: 'Ludwig Mies van der Rohe', source: 'in G magazine, 1923' },
  { text: 'Architecture begins when you place two bricks carefully together.', author: 'Ludwig Mies van der Rohe', source: 'attributed, IIT lectures' },
  { text: 'Architecture is the art of how to waste space.', author: 'Philip Johnson', source: 'New York Times, 1964' },
  { text: 'All great architecture is the design of space that contains, cuddles, exalts, or stimulates the persons in that space.', author: 'Philip Johnson', source: 'address, 1975' },
  { text: 'You employ stone, wood and concrete, and with these you build houses and palaces: that is construction. But suddenly you touch my heart, you do me good, I am happy and I say: this is beautiful. That is architecture.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923' },
  { text: 'Space and light and order: those are the things that men need just as much as they need bread or a place to sleep.', author: 'Le Corbusier', source: 'attributed, 1961' },
  { text: 'Even a common, ordinary brick wants to be something more than it is. It aspires.', author: 'Louis Kahn', source: 'lecture, University of Pennsylvania, c. 1971' },
  { text: 'Architecture is the thoughtful making of spaces.', author: 'Louis Kahn', source: 'in Perspecta, 1957' },
  { text: 'A bicycle shed is a building; Lincoln Cathedral is a piece of architecture.', author: 'Nikolaus Pevsner', source: 'An Outline of European Architecture, 1943' },
  { text: 'Modern architecture died in St Louis, Missouri, on 15 July 1972, at 3.32 in the afternoon.', author: 'Charles Jencks', source: 'The Language of Post-Modern Architecture, 1977' },
  { text: 'In all matters, but particularly in architecture, there are these two points: the thing signified, and that which gives it its significance.', author: 'Vitruvius', source: 'De Architectura, Book I, ch. 1 (Morgan trans.)' },
  { text: 'Order gives due measure to the members of a work considered separately, and symmetrical agreement to the proportions of the whole.', author: 'Vitruvius', source: 'De Architectura, Book I, ch. 2 — on Order (Morgan trans.)' },
  { text: 'Eurythmy is beauty and fitness in the adjustments of the members.', author: 'Vitruvius', source: 'De Architectura, Book I, ch. 2 — on Eurythmy (Morgan trans.)' },
  { text: 'Without symmetry and proportion there can be no principles in the design of any temple; that is, if there is no precise relation between its members, as in the case of those of a well-shaped man.', author: 'Vitruvius', source: 'De Architectura, Book III, ch. 1 (Morgan trans.)' },
  { text: 'The little rustic cabin is the model upon which all the magnificences of architecture have been imagined.', author: 'Marc-Antoine Laugier', source: 'An Essay on Architecture, 1753 (1755 English trans.)' },
  { text: 'No good work whatever can be perfect, and the demand for perfection is always a sign of a misunderstanding of the ends of art.', author: 'John Ruskin', source: '"The Nature of Gothic", The Stones of Venice, 1853' },
  { text: 'In all things that live there are certain irregularities and deficiencies which are not only signs of life, but sources of beauty.', author: 'John Ruskin', source: '"The Nature of Gothic", The Stones of Venice, 1853' },
  { text: 'The styles are a lie. Style is a unity of principle animating all the work of an epoch, the result of a state of mind which has its own special character.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923 (Etchells trans.)' },
  { text: 'The plan is the generator. Without a plan, you have lack of order, and wilfulness.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923 (Etchells trans.)' },
  { text: 'Greece, and in Greece the Parthenon, marked the apogee of this pure creation of the mind.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923 (Etchells trans.)' },
  { text: 'The Engineer\'s aesthetic and Architecture are two things that march together and follow one from the other.', author: 'Le Corbusier', source: 'Towards a New Architecture, 1923 (Etchells trans.)' },
  { text: 'Flowers or other natural objects should not be used as ornaments, but conventional representations of them.', author: 'Owen Jones', source: 'The Grammar of Ornament, Proposition 13, 1856' },
  { text: 'All ornament should be based upon a geometrical construction.', author: 'Owen Jones', source: 'The Grammar of Ornament, Proposition 8, 1856' },
  { text: 'The space within becomes the reality of the building.', author: 'Frank Lloyd Wright', source: 'from his reading of Laozi; stated in his lectures and writings' },
  { text: 'The straight line belongs to men, the curved one to God.', author: 'Antoni Gaudi', source: 'attributed, on the forms of nature' },
  { text: 'Architecture begins where engineering ends.', author: 'Walter Gropius', source: 'address, Harvard Department of Architecture' },
  { text: 'Always design a thing by considering it in its next larger context — a chair in a room, a room in a house, a house in an environment, an environment in a city plan.', author: 'Eliel Saarinen', source: 'quoted in Time magazine, 2 July 1956' },
  { text: 'Architecture should be silent, and let nature, in the guise of sunlight and wind, speak.', author: 'Tadao Ando', source: 'interviews on his work with light and concrete' },
];

window.THOUGHTS = [
  { text: "Vitruvius set three tests for any building, and they still hold. Firmitas — does it stand, honestly and for a long time? Utilitas — does it serve the life that goes on inside it? Venustas — does it give delight to the eye? A building that fails any one of the three is not yet finished, however clever it may be. Carry the three words as you walk today, and try them on the first building that stops you.", source: 'after Vitruvius, De Architectura' },
  { text: "The classical orders are not decoration added to a building; they are a way of thinking about load and support made visible. The column carries, the entablature is carried, and every moulding tells you which is which. Once you see a façade as a quiet argument about weight — this part presses down, this part pushes back — you are reading architecture the way its builders meant it to be read.", source: 'on the logic of the orders' },
  { text: "Palladio built for working farms in the Veneto, yet his villas look like temples. That was deliberate. He held that the dignity we give to gods and rulers should also be given to the ordinary business of living well — that a house for a family and its land deserved harmony, symmetry and a noble front. The country house you admire on a grand estate is, at root, his idea travelling north.", source: 'on Palladio and the villa' },
  { text: "A revival is never a copy. When the Victorians raised a Greek-columned bank or a Gothic town hall, they were choosing a language to say something about themselves — permanence, civic pride, a claim to inherit Athens or the medieval city. When you meet a classical building that is clearly not ancient, ask what its builders wanted you to feel. The style is an argument, and the argument is usually about trust.", source: 'on the meaning of revival' },
  { text: "Symmetry does more work than we notice. A symmetrical front tells the eye where the important door is, holds the whole composition still, and lets ornament gather at the centre and the ends where it counts. Break the symmetry and a classical building becomes uneasy; keep it, and even a plain wall feels resolved. Watch today for how a good façade uses its middle and its edges.", source: 'on symmetry and repose' },
  { text: 'When a column carries a load, its thickness is not a matter of taste. It answers to weight, to stone, to the height it must reach. Proportion in the old sense is not decoration laid over a building; it is the felt harmony between what a thing does and how large it is. Stand before a good facade and notice whether the parts seem to belong to one another before you know why.', source: 'after Vitruvius / classical tradition' },
  { text: 'A great column may be plain, and a small one richly carved, and both be right. The Greeks would not have crowned a warehouse with the same ornament as a temple. What suits one purpose insults another. Look today for decorum: whether the grandeur of a building matches the seriousness of what it is for, or whether it is dressed above its station.', source: 'after Vitruvius / classical tradition' },
  { text: 'Ruskin asked us to build as if for ever, not for present use alone. A wall raised in that spirit is a gift to people we will never meet, whose thanks we will never hear. When you pass an old building today, remember you are the descendant its makers were thinking of. Ask what you, in turn, are leaving to the strangers who come after.', source: 'after John Ruskin' },
  { text: 'Iron wants to be thin and to span; stone wants to be stacked and to bear. To make iron pretend to be stone, or plaster pretend to be marble, is a small lie built into the walls. Honesty of materials means letting each thing show what it is and do what it can. Look for where a building tells the truth about how it stands up.', source: 'after Pugin / Ruskin' },
  { text: 'Alberti called beauty concinnitas: the state where nothing can be added or taken away without making the thing worse. It is not richness but rightness. You can test it by imagination. Take away a window, widen a doorway, raise the roof a little in your mind. If every change makes the whole feel poorer, you are standing in front of concinnitas.', source: 'after Leon Battista Alberti' },
  { text: 'Palladio did not begin by inventing. He went to Rome and measured the ruins with his own hands, minutely, again and again, until the ancient buildings had passed through his fingers into his understanding. Mastery in any art seems to start this way: patient imitation of the best, long before invention. First learn to see truly what already stands.', source: 'after Andrea Palladio' },
  { text: 'Sullivan watched the eagle, the oak, the open apple-blossom, and saw one law: form follows function. Where the purpose does not change, the shape does not change. Before judging whether a building is handsome, ask first what it is trying to do, and whether its shape is honestly the answer to that.', source: 'after Louis Sullivan' },
  { text: 'Le Corbusier said our eyes are made to see forms in light, and that architecture is the play of masses brought together in light. Light is not something added to a building; it is one of its materials, as real as the stone. Watch a plain wall across the hours. The same mass becomes a different thing as the sun moves. The architect was building with that movement.', source: 'after Le Corbusier' },
  { text: 'Pope told the gardener to consult the genius of the place: to read the fall of the water, the ambition of the hill, and to build in agreement with it rather than against it. A building can obey the same counsel. Ask of any new thing whether it listened to its ground, its neighbours, its weather, or whether it was set down as if the place were blank.', source: 'after Alexander Pope' },
  { text: 'Burke found the sublime in what suspends the mind: vast dimension, deep shadow, power beyond our measure. Astonishment, he said, is that state in which all the soul\'s motions are stilled. A cathedral nave and a bare cliff can do the same work. When a building makes you fall silent and feel small in a way that enlarges you, you are meeting the sublime.', source: 'after Edmund Burke' },
  { text: 'Pugin allowed no feature that was not needed for convenience, construction, or propriety, and let ornament only enrich what already had to be there. This is a discipline against showing off. Ornament earns its place when it makes a necessary thing more clearly itself, and cheapens the whole when it is tacked on merely for effect.', source: 'after A. W. N. Pugin' },
  { text: 'Owen Jones held that architecture is the material expression of the wants and sentiments of its age. Every building is a kind of confession about the people who raised it: what they valued, feared, and hoped. Walk through a street reading it that way. The stone is telling you what the age loved. Ask what our own buildings confess about us.', source: 'after Owen Jones' },
  { text: 'Wotton\'s old triad still holds: commodity, firmness, and delight, tempered so that none is wanting and none in excess. A building that is only useful is mean; only strong, brutal; only beautiful, false. The art is in the balance. Try weighing a familiar building on all three at once, and notice which leg the maker cared about least.', source: 'after Henry Wotton' },
  { text: 'Kahn spoke of silence and light meeting at a threshold — Silence the desire to be, Light the giver of all presence. Wall and window are how a room takes hold of daylight. Sit in a good room and watch how it gathers, softens, and moves the light. The architect was composing that, as a musician composes sound.', source: 'after Louis Kahn' },
  { text: 'Wren said architecture aims at eternity, and is therefore the one thing incapable of modes and fashions in its principles. Fashion changes yearly; the reasons of statics and optics do not. It steadies the eye to separate the two when looking at a building: which parts are merely of their moment, and which answer to something that will not go out of date.', source: 'after Christopher Wren' },
  { text: 'The best builders of the old cathedrals left no names on their finest carvings. The work was offered to something larger than the maker, and the pride was in the whole, not the signature. There is a freedom in egoless making: you stop asking whether the thing shows you off, and ask only whether it is true and good.', source: 'after the medieval / classical tradition' },
  { text: 'Ruskin defended the rough, imperfect carving of the medieval workman over the machine-smooth copy, because the roughness held a living mind at work. A perfect thing made by an unfree hand is poorer than an imperfect thing made by a free one. When you see the small irregularities of handwork in old stone, read them not as faults but as the signature of a man who was allowed to think.', source: 'after John Ruskin' },
  { text: 'The classical orders were learned by copying, drawing, and measuring for years before anyone was trusted to depart from them. Invention was earned, not assumed. In any craft the sequence seems the same: first imitate the masters until their sense lives in your hand, then, and only then, begin to say something of your own.', source: 'after the classical tradition' },
  { text: 'Mastery in building was never counted in months. The apprentice ground stone and drew mouldings for years, and the great works came late. A cathedral could take three generations, so that the man who laid the foundation never saw the vault. Ask what in your own work is being built for a completion you may not live to see.', source: 'after the medieval / classical tradition' },
  { text: 'Vitruvius wanted the architect to know geometry and history, music and medicine, law and the stars, because a building touches all of life and must answer to all of it. Narrow skill is not enough for a broad art. Cultivate a wide, curious eye: the more of the world you understand, the more of it a single well-made building can be made to hold.', source: 'after Vitruvius' },
  { text: 'Laugier asked us to imagine architecture reduced to its first necessity: four tree-trunks for columns, four beams laid across them, and a pitched roof of branches — the primitive hut. Everything beyond that, he argued, must justify itself against this simple frame. It is a bracing test to carry through a street: look at a façade and ask which parts are the true structure of shelter, and which are habit, memory or show. The exercise does not condemn ornament, but it does ask ornament to know its place.', source: 'after Marc-Antoine Laugier' },
  { text: 'Winckelmann summed up the Greek achievement as noble simplicity and calm grandeur, and the phrase is worth carrying because it names a power we often overlook: the power of restraint. A plain Doric temple says less than a Baroque church, and by saying less it can feel graver, surer, more at rest. Before you praise a building for what it adds, notice for a moment what a good one has had the confidence to leave out.', source: 'after Johann Joachim Winckelmann' },
  { text: 'The old builders took the measure of their columns and rooms from the proportions of the human body — the foot, the palm, the span, the standing figure with arms outstretched. That is why a well-made classical room so often feels right the moment you step into it: its dimensions are quietly keyed to yours. Stand in a space you find comfortable and ask whether it was built to the scale of a person, or to the scale of a drawing.', source: 'after Vitruvius and Alberti' },
  { text: 'Ledoux and Boullee dreamed of buildings whose very shape would announce their purpose — a "speaking architecture", where a courthouse looked just, a monument looked solemn, a place of pleasure looked glad. Not every building can or should shout its use so plainly, but the idea sharpens the eye. Ask of a building what it is trying to say about itself, and whether its form is telling the truth about what goes on inside.', source: 'after Claude-Nicolas Ledoux' },
  { text: 'Geoffrey Scott argued that we read buildings through our own bodies: we lend a column our sense of standing, a vault our sense of spanning, a heavy base our sense of bearing weight. A building moves us because we unconsciously imagine ourselves doing what it does. Next time a colonnade or a staircase stirs you, notice that the feeling begins in your own muscles — you are, in a small way, standing and rising along with the stone.', source: 'after Geoffrey Scott' },
  { text: 'Ruskin\'s Lamp of Sacrifice praised the labour lavished where no one would ever see it — the finished back of a statue, the carving high in the dark of a vault. To give care to the unseen is to build for something beyond applause. It is a discipline worth borrowing far from architecture: to do the hidden part of any work as well as the part that shows, because the doing is itself the point.', source: 'after John Ruskin' },
  { text: 'William Morris left one rule for the home that has never been bettered: have nothing in your houses that you do not know to be useful, or believe to be beautiful. It is harder than it sounds, because idle, half-liked things crowd out both the useful and the beautiful without our noticing. Look around one room today and weigh each thing against Morris\'s two tests; what survives both is what the room is truly for.', source: 'after William Morris' },
  { text: 'Camillo Sitte looked at the great old squares of Europe and saw that their charm was not accident but art: the slightly irregular shape, the enclosing walls, the monument set off-centre where it could be seen whole. He warned against planning a city like a chessboard on a drawing-board, forgetting that people move through it at eye level. Walk a square you love and notice how it holds you — the good ones are composed, not merely laid out.', source: 'after Camillo Sitte' },
  { text: 'The Doric corner hid a famous impossibility. The rule said a triglyph should sit centred over every column and every gap, and also that the frieze must end with a triglyph at the very corner — and the two cannot both be true. Greek builders quietly adjusted the last spacings rather than break the corner. It is a small, honest lesson: even the most rational system meets a point where it must choose grace over the letter of its own law.', source: 'on the Doric order' },
  { text: 'The Parthenon has almost no straight lines. Its columns lean gently inward, swell at the middle, and stand a little closer together at the corners; its platform curves faintly upward. Every one of these departures is a correction for the eye, which would otherwise read true straightness as sagging or splayed. Classical perfection, it turns out, is not rigid geometry but a subtle bending of the rules so that the building looks right, not merely measures right.', source: 'on the refinements of the Parthenon' },
  { text: 'We picture ancient Greece in cool white marble, but the temples were once painted in strong reds, blues and golds, their carvings bright against the stone. The serene whiteness we admire is partly the work of time, which stripped the colour away, and partly a modern taste that came to prefer the bare stone. It is worth remembering when we call a thing "classical purity": some of that purity is loss, mistaken for design.', source: 'on Greek polychromy' },
  { text: 'The tidy scheme of "the five orders", climbing from plain Tuscan to rich Composite, feels ancient, but it was largely assembled by Renaissance theorists ordering a past that had been looser and more various. Antiquity built in these forms without ever quite codifying them into a single ladder. It is a useful caution whenever a subject is handed to us as a neat system: ask how much of the neatness belongs to the thing, and how much to the people who later arranged it.', source: 'on the canon of the orders' },
  { text: 'Sullivan watched the new steel frame rise and argued that the tall building should express its own nature — its height, its structure, its function — rather than hide behind a borrowed classical mask. Whether or not you accept where the argument led, the question it asks of any building is a fair one: is the outside telling the truth about how this thing is built and what it is for, or is it a costume? Honesty of expression is not the only virtue, but it is a real one.', source: 'after Louis Sullivan' },
  { text: 'Le Corbusier called a house a machine for living in — a deliberate provocation, meant to strip away sentiment and ask what a dwelling must actually do. It is worth weighing rather than simply cheering or dismissing. A house that works like a good tool is a real gift; a house that is only a tool, and never a home, has lost something the word "machine" cannot hold. The best building answers both the engineer and the heart.', source: 'after Le Corbusier' },
  { text: 'For centuries the finest carving in a cathedral might carry no name at all. The work was offered to something larger than the maker, and the pride was in the whole, not the signature. There is a strange freedom in that kind of making: when you stop asking whether the thing shows you off, you are left only with the better question — whether it is true and good. Much anonymous stone was cut in exactly that spirit.', source: 'on the anonymous masters' },
  { text: 'A medieval cathedral could take three or four generations to build, so that the man who laid the foundation never saw the vault, and the master who began the towers knew his grandchildren might finish them. To work like that is to accept that your best work may be completed by hands you will never shake. Ask what in your own life is being built for a day you may not live to see — and whether that changes how you lay the stones.', source: 'on the long labour of building' },
  { text: 'Alberti held that a building exists first as an idea of order — its lineaments, the pattern of its parts — quite apart from the stone or brick that will later carry it. The same design can be raised in marble or in humble materials and remain the same design. It is a quietly encouraging thought for any maker: settle the shape of the thing clearly in the mind, and the material, whatever it turns out to be, has something true to serve.', source: 'after Leon Battista Alberti' },
  { text: 'Burke found the sublime not in what is pretty but in what overwhelms: vast size, deep shadow, a power beyond our measure, before which the mind falls still. A cathedral nave and a bare cliff can do the same work, stopping the chatter of thought and leaving only awe. When a building makes you fall silent and feel small in a way that somehow enlarges you, you have met the sublime — and it is worth seeking out on purpose.', source: 'after Edmund Burke' },
  { text: 'The old treatises insisted that the architect study far more than building: geometry and history, music and medicine, law and the motion of the stars. The reason was simple — a building touches every part of life and must answer to all of it. It is a case for the wide, curious mind against the narrow specialist. The more of the world you understand, the more of it a single well-made thing can be made to hold.', source: 'after Vitruvius' },
  { text: 'Palladio gave the country house a temple front, lifting the ordinary business of farming and living toward dignity and repose. He held that the harmony we reserve for temples and palaces could also grace a working house on its land. It is a generous idea: that beauty and proportion are not only for the grand and the sacred, but belong by right to daily life — that where we eat and sleep deserves to be made well.', source: 'after Andrea Palladio' },
];

window.VERSES = [
  { title: 'Firmness, commodity, delight', text: 'Firmitas. Utilitas. Venustas.\n\nIt must stand. It must serve. It must delight.', author: 'Vitruvius, by way of Sir Henry Wotton', note: 'The oldest test in the book, and still the best. Three words — learn them in both tongues.' },
  { title: 'The parts and the whole', text: 'The beauty of a building lies in the agreement of the parts with one another, and of every part with the whole.', author: 'after Alberti and Palladio', note: 'Say it, then look for the building around you that obeys it — and the one that does not.' },
  { title: 'The order of the orders', text: 'Tuscan. Doric. Ionic. Corinthian. Composite.\n\nPlainest and strongest first; richest and most slender last.', author: 'the classical canon', note: 'Learn the five in order. Everything in the tradition is written in these letters.' },
  { title: 'Servant and served', text: 'The column carries. The entablature is carried. Every moulding says which is which.', author: 'on reading a façade', note: 'A rule for the eye. Hold it, and a colonnade stops being pattern and becomes an argument about weight.' },
  { title: 'On ornament', text: 'Ornament should grow from the building, as the leaf grows from the branch — never stuck on, always belonging.', author: 'after Ruskin and Pugin', note: 'The test of good enrichment: could you remove it without leaving a wound? If yes, it was never part of the building.' },
  { title: 'Order', text: 'Give each part its due measure,\nand fit the parts to the whole.', author: 'Vitruvius — the first of six principles', note: 'Order is a chosen module repeated: a column\'s width setting the spacing, the door, the whole grid.' },
  { title: 'Arrangement', text: 'Put things in their proper places\nwith fitness of effect.', author: 'Vitruvius (dispositio)', note: 'Read a facade as plan, elevation and view together — arrangement is how those three agree.' },
  { title: 'Eurythmy', text: 'Let height suit breadth, and breadth suit length,\nso the parts answer one another.', author: 'Vitruvius (eurythmia)', note: 'Stand back: if nothing looks too tall, too squat or too thin, you are seeing eurythmy at work.' },
  { title: 'Symmetry', text: 'Relate every part to the whole\nthrough one agreed standard.', author: 'Vitruvius (symmetria)', note: 'Find the unit — often the column base — and watch it govern the whole building\'s proportions.' },
  { title: 'Propriety', text: 'Let the building suit its purpose,\nits site, and its custom.', author: 'Vitruvius (decor / propriety)', note: 'A bank looks solid, a chapel looks quiet. Propriety is a building dressed for its job.' },
  { title: 'Economy', text: 'Manage means and materials well;\nbuild fit for those who use it.', author: 'Vitruvius (distributio / economy)', note: 'Economy is not cheapness — it is nothing wasted and nothing missing for the people who live there.' },
  { title: 'Concinnitas', text: 'Beauty is a harmony of all the parts,\nso that nothing could be added,\ntaken away, or altered but for the worse.', author: 'Alberti, De Re Aedificatoria', note: 'Test a good elevation by imagining one change — if every change spoils it, you have found concinnitas.' },
  { title: 'Ornament as Auxiliary Light', text: 'Beauty is inborn in the building;\nornament is a brightness added to it,\na kind of auxiliary light.', author: 'Alberti', note: 'Strip the ornament away in your mind — if the form is still beautiful, the ornament was doing its true job.' },
  { title: 'The Beautiful Room Shapes', text: 'The finest rooms follow set ratios:\nthe square, the square-and-a-third,\nthe square-and-a-half, the double square.', author: 'Palladio', note: 'Pace out a handsome room; its length and width will often sit near one of these simple ratios.' },
  { title: 'Consult the Genius of the Place', text: 'In all, let Nature never be forgot.\nConsult the genius of the place.', author: 'Alexander Pope, Epistle to Burlington', note: 'Before judging a building, look where it sits — the good ones answer their hill, river or street.' },
  { title: 'Entasis', text: 'Swell the column\'s shaft gently,\nso the eye reads it as straight and alive.', author: 'Greek practice (Vitruvius III)', note: 'A dead-straight column looks pinched; the slight bulge is a correction made for your eye, not the ruler.' },
  { title: 'Two True Principles', text: 'No feature that is not necessary for\nconvenience, construction or propriety;\nall ornament the enrichment of\nthe essential construction.', author: 'A. W. N. Pugin, True Principles', note: 'Ask of any detail: does it hold something up, or only pretend to? Pugin wants no pretending.' },
  { title: 'The Lamp of Sacrifice', text: 'Offer to the work what is precious,\nnot merely what is useful.', author: 'Ruskin, Seven Lamps of Architecture', note: 'The carved corner you will never touch is sacrifice — care given where no one is watching.' },
  { title: 'The Lamp of Truth', text: 'Let the building be honest:\nno false structure, no fake material,\nno machine-made pretending to be hand.', author: 'Ruskin, Seven Lamps', note: 'Tap a column: is the marble real or painted plaster? Truth is a building that hides nothing.' },
  { title: 'The Lamp of Power', text: 'Seek the grandeur of mass and shadow;\nnever break the great bounding line.', author: 'Ruskin, Seven Lamps', note: 'Squint at the silhouette against the sky — powerful buildings keep one strong, unbroken outline.' },
  { title: 'The Lamp of Beauty', text: 'Draw ornament from nature\'s own forms;\nwhat is ugly in the field is ugly on the wall.', author: 'Ruskin, Seven Lamps', note: 'Good carving remembers leaves, vines and shells — beauty is borrowed from living things.' },
  { title: 'The Lamp of Life', text: 'Let the work show the hand and the joy\nof the man who made it.', author: 'Ruskin, Seven Lamps', note: 'Two carvings never quite alike — that liveliness is a human hand, not a stamping machine.' },
  { title: 'The Lamp of Memory', text: 'Build as if to last, so buildings\nbecome the memory of a people.', author: 'Ruskin, Seven Lamps', note: 'An old wall is a record — we build not only for ourselves but for those not yet born.' },
  { title: 'The Lamp of Obedience', text: 'Freedom in building comes through\nsubmission to a shared, disciplined style.', author: 'Ruskin, Seven Lamps', note: 'A street feels whole when its houses obey one language — obedience is what lets many hands agree.' },
  { title: 'Decorate Construction', text: 'Construction should be decorated.\nDecoration should never be\npurposely constructed.', author: 'Owen Jones, Grammar of Ornament', note: 'Beautify the beam that is really holding the roof; never add a fake beam just to decorate.' },
  { title: 'Fitness First', text: 'Form should be governed by fitness;\nbeauty grows from that fitness fulfilled.', author: 'Owen Jones, Grammar of Ornament', note: 'The most beautiful things are those that do their job most exactly — start with the use, not the decoration.' },
  { title: 'The Primitive Hut', text: 'All the magnificence of architecture\nis born from the simple hut:\nthe upright column, the resting beam,\nthe sheltering pediment.', author: 'after Marc-Antoine Laugier, Essay on Architecture, 1753', note: 'Reason a building back to its bones. Whatever is not column, beam or gable is convention — useful to know which is which.' },
  { title: 'No Reason, No Column', text: 'Where there is no reason,\nlet there be no column, no pilaster, no arch.', author: 'Marc-Antoine Laugier', note: 'A hard test against decoration for its own sake: ask of every part whether it is doing a job, or only pretending to.' },
  { title: 'Noble Simplicity', text: 'Noble simplicity\nand calm grandeur.', author: 'Johann Joachim Winckelmann, 1755', note: 'The Greek ideal in three words. Much of a building\'s power is in what has been left out.' },
  { title: 'Character', text: 'Give a building the face of its purpose,\nso that its use can be read in its form.', author: 'after Ledoux and Boullee', note: 'A prison should look grave, a theatre glad. The eye should half-know what a building is for before it is told.' },
  { title: 'Truth to Materials', text: 'Let stone be stone and iron be iron;\nno material should wear the mask of another.', author: 'after Pugin and Ruskin', note: 'Painted plaster pretending to be marble is a small lie built into the wall. Look for where a building tells the truth about itself.' },
  { title: 'Man the Measure', text: 'Take the measure of the parts from the body of a man,\nfor in him nature has set the proportions.', author: 'after Vitruvius, De Architectura III', note: 'Classical proportion is rooted in the human frame — one reason a well-made room feels right to stand inside.' },
  { title: 'Solidity Below, Lightness Above', text: 'Set the plain and strong at the foot,\nthe rich and slender at the crown.', author: 'the hierarchy of the orders', note: 'Tuscan and Doric below, Corinthian and Composite above: the visual weight lightens as the eye climbs.' },
  { title: 'The Capital Names the Order', text: 'Read the head of the column:\nplain cushion, scroll, or leaf.', author: 'the classical canon', note: 'The quickest identification in all of architecture. Plain = Doric or Tuscan; scrolls = Ionic; leaves = Corinthian.' },
  { title: 'Firm to the Ground', text: 'Carry the foundations down to solid ground,\nand choose the materials well and freely.', author: 'Vitruvius, on durability', note: 'Firmitas begins unseen, below the earth. The most honest part of a building is the part no one admires.' },
  { title: 'Nothing Wanting, Nothing in Excess', text: 'Temper the three conditions together,\nthat none may be wanting, and none in excess.', author: 'Sir Henry Wotton, 1624', note: 'A building only useful is mean; only strong, brutal; only beautiful, false. The art is the balance.' },
  { title: 'Aims at Eternity', text: 'Build on the reasons of statics and optics,\nnot on the modes and fashions of the year.', author: 'after Sir Christopher Wren', note: 'Fashion changes; the reasons of weight and sight do not. Separate the part that is merely of its moment from the part that will last.' },
  { title: 'First Delight, Then Instruct', text: 'Let the building please the eye first,\nand so open the mind to be taught.', author: 'Karl Friedrich Schinkel, 1828', note: 'A museum or a hall that gives pleasure at the door has already begun its lesson before a word is read.' },
  { title: 'Useful or Beautiful', text: 'Have nothing in your houses\nthat you do not know to be useful,\nor believe to be beautiful.', author: 'William Morris, 1880', note: 'A rule for a room as much as a building: everything earns its place by use or by beauty, and idle things crowd both out.' },
  { title: 'The Play of Masses in Light', text: 'Our eyes are made to see forms in light;\nlight and shade reveal these forms.', author: 'Le Corbusier, 1923', note: 'Light is a material, not an afterthought. Watch a plain wall across a day and see how the sun rebuilds it hour by hour.' },
  { title: 'Learn the Language First', text: 'Imitate the masters until their sense\nlives in your hand;\nthen, and only then, speak.', author: 'the classical tradition', note: 'Invention is earned, not assumed. You win the right to a new sentence only after you have learned to write the old ones.' },
  { title: 'Decorum', text: 'Let the grandeur of a building\nmatch the seriousness of its office.', author: 'after Vitruvius (decor)', note: 'A bank looks solid, a chapel quiet, a barn plain. Propriety is a building dressed correctly for its work — never above its station.' },
  { title: 'Shadow Is the Cornice’s Work', text: 'Let the crowning band jut out\nand cast its line of shadow,\nso the wall is finished against the sky.', author: 'on reading a cornice', note: 'The projecting cornice both sheds the rain and draws a dark line at the top of the wall — the building\'s last, decisive edge.' },
  { title: 'Design Before Matter', text: 'The same design lives\nin many buildings of many materials;\nfirst it is made whole in the mind.', author: 'after Leon Battista Alberti', note: 'Alberti\'s lineaments: a building is an idea of order before it is a single stone. Settle the design, and half the work is already done.' },
];

window.PASSAGES = [
  { title: 'The three departments of architecture', source: 'Vitruvius, De Architectura, Book I (Morgan trans.)', text: 'All these must be built with due reference to durability, convenience, and beauty. Durability will be assured when foundations are carried down to the solid ground and materials wisely and liberally selected; convenience, when the arrangement of the apartments is faultless and presents no hindrance to use, and when each class of building is assigned to its suitable and appropriate exposure; and beauty, when the appearance of the work is pleasing and in good taste, and when its members are in due proportion according to correct principles of symmetry.' },
  { title: 'On the well-ordered house', source: 'Andrea Palladio, The Four Books of Architecture, Book II', text: 'As in the human body there are some parts noble and beautiful, and others rather ignoble and disagreeable, and yet we see that the former have great need of the latter, and that they could not subsist without them; so in a building there ought to be some parts considerable and honoured, and some less elegant; without which the former could not remain free, and would in part lose somewhat of their dignity and beauty.\n\nThe beauty will result from the beautiful form and from the correspondence of the whole to the parts, of the parts amongst themselves, and of these again to the whole; so that the structure may appear an entire and complete body, wherein each member agrees with the other, and all the members are necessary for the accomplishment of the building.' },
  { title: 'The lamp of memory', source: 'John Ruskin, The Seven Lamps of Architecture, 1849', text: 'When we build, let us think that we build for ever. Let it not be for present delight, nor for present use alone; let it be such work as our descendants will thank us for, and let us think, as we lay stone on stone, that a time is to come when those stones will be held sacred because our hands have touched them, and that men will say, as they look upon the labour and wrought substance of them, "See! this our fathers did for us."\n\nFor, indeed, the greatest glory of a building is not in its stones, nor in its gold. Its glory is in its Age, and in that deep sense of voicefulness, of stern watching, of mysterious sympathy, which we feel in walls that have long been washed by the passing waves of humanity.' },
  { title: 'On imitation and invention', source: 'Leon Battista Alberti, On the Art of Building, c. 1450', text: 'I will not deny that it is convenient to imitate those who have built well before us, and that the surest way to good building is to follow the reasons of those whom experience has approved. Yet we should not so bind ourselves to imitation as to lose our own judgement; for the ancients themselves, whom we so justly admire, did not so much follow others as follow Nature, who is the surest guide of all. Take from the ancients their reasons, not merely their forms; for it is by understanding why a thing was done that we learn to do well ourselves.' },
  { title: 'The Education of the Architect', source: 'Vitruvius (trans. Morgan), The Ten Books on Architecture, Book I', text: 'The architect should be equipped with knowledge of many branches of study, for it is by his judgement that all work done by the other arts is put to test.\nLet him be educated, skilful with the pencil, instructed in geometry, know much history, have followed the philosophers with attention, understand music, have some knowledge of medicine, know the opinions of the jurists, and be acquainted with astronomy.\nHe ought to be both naturally gifted and amenable to instruction. Neither natural ability without instruction nor instruction without natural ability can make the perfect artist.' },
  { title: 'The Glory of Age', source: 'John Ruskin, The Seven Lamps of Architecture, "The Lamp of Memory," 1849', text: 'For, indeed, the greatest glory of a building is not in its stones, or in its gold. Its glory is in its Age, and in that deep sense of voicefulness, of stern watching, of mysterious sympathy, nay, even of approval or condemnation, which we feel in walls that have long been washed by the passing waves of humanity.' },
  { title: 'The Freedom of the Workman', source: 'John Ruskin, The Stones of Venice, "The Nature of Gothic," 1853', text: 'You must either make a tool of the creature, or a man of him. You cannot make both.\nMen were not intended to work with the accuracy of tools, to be precise and perfect in all their actions. If you will have that precision out of them, you must unhumanize them.\nLet him but begin to imagine, to think, to try to do anything worth doing, and out come all his roughness, all his dulness, all his incapacity — but out comes the whole majesty of him also.' },
  { title: 'Concinnitas', source: 'Leon Battista Alberti, On the Art of Building, Book VI, c. 1450', text: 'Beauty is that reasoned harmony of all the parts within a body, so that nothing may be added, taken away, or altered, but for the worse.\nWhen the mind is reached by way of the sight, or the sound, it soon perceives this harmony; for by nature we long for things finished and complete, and cling to whatever is agreeable and worthy.\nWhere concinnitas is present, there the eye rests, and the whole is felt as one.' },
  { title: 'Measured With My Own Hands', source: 'after Andrea Palladio (trans. Ware, 1738), The Four Books of Architecture, 1570', text: 'Guided by a natural inclination, I gave myself up in my early years to the study of architecture; and as it was always my opinion that the ancient Romans far excelled all who have come after them, so I proposed to myself Vitruvius both as master and guide.\nI set myself to search into the ruins of those ancient edifices which, in despite of time and the cruelty of the Barbarians, still remain; and finding them much more worthy of study than at first I had imagined, I began very minutely to measure every one of their parts.' },
  { title: 'Form Ever Follows Function', source: 'Louis H. Sullivan, "The Tall Office Building Artistically Considered," 1896', text: 'It is the pervading law of all things organic and inorganic, of all things physical and metaphysical, of all things human and superhuman, that the life is recognizable in its expression, that form ever follows function. This is the law.\nWhether it be the sweeping eagle in his flight, or the open apple-blossom, the toiling work-horse, the branching oak, the winding stream at its base, form ever follows function, and this is the law. Where function does not change, form does not change.' },
  { title: 'The Play of Masses in Light', source: 'Le Corbusier (trans. Etchells), Towards a New Architecture, 1927', text: 'Our eyes are made to see forms in light; light and shade reveal these forms; cubes, cones, spheres, cylinders and pyramids are the great primary forms which light reveals to advantage.\nIt is for this reason that these are beautiful forms, the most beautiful forms.\n"Architecture is the masterly, correct and magnificent play of masses brought together in light."' },
  { title: 'Consult the Genius of the Place', source: 'Alexander Pope, Epistle to Lord Burlington, 1731', text: 'To build, to plant, whatever you intend,\nTo rear the column, or the arch to bend,\nTo swell the terrace, or to sink the grot;\nIn all, let Nature never be forgot.\nConsult the Genius of the Place in all,\nThat tells the waters or to rise, or fall,\nCalls in the country, catches opening glades,\nJoins willing woods, and varies shades from shades,\nNow breaks, or now directs, th\' intending lines;\nPaints as you plant, and, as you work, designs.' },
  { title: 'Astonishment', source: 'Edmund Burke, A Philosophical Enquiry, 1757', text: 'The passion caused by the great and sublime in nature, when those causes operate most powerfully, is Astonishment; and astonishment is that state of the soul in which all its motions are suspended, with some degree of horror.\nIn this case the mind is so entirely filled with its object, that it cannot entertain any other, nor reason on that object which employs it. Hence arises the great power of the sublime, that it anticipates our reasonings, and hurries us on by an irresistible force.' },
  { title: 'The Two True Principles', source: 'A. W. N. Pugin, The True Principles of Pointed or Christian Architecture, 1841', text: 'The two great rules for design are these: first, that there should be no features about a building which are not necessary for convenience, construction, or propriety; second, that all ornament should consist of enrichment of the essential construction of the building.\nThe neglect of these two rules is the cause of all the bad architecture of the present time. Architectural features are continually tacked on buildings with which they have no connection, merely for the sake of what is termed effect.' },
  { title: 'The Expression of an Age', source: 'Owen Jones, The Grammar of Ornament, "General Principles," 1856', text: 'Proposition 1. The Decorative Arts arise from, and should properly be attendant upon, Architecture.\nProposition 2. Architecture is the material expression of the wants, the faculties, and the sentiments, of the age in which it is created.\nProposition 5. Construction should be decorated. Decoration should never be purposely constructed. That which is beautiful is true; that which is true must be beautiful.' },
  { title: 'Commodity, Firmness and Delight', source: 'Sir Henry Wotton, The Elements of Architecture, 1624', text: 'In Architecture, as in all other operative Arts, the end must direct the operation. The end is to build well.\nWell-building hath three conditions: Commodity, Firmness, and Delight; where the first is the use, the second the strength, and the third the beauty.\nAnd these must be so tempered together, that none may be wanting, and none in excess; for the whole edifice is but one entire and perfect thing, whereof the parts are so knit that the failing of one endangers all.' },
  { title: 'Silence and Light', source: 'after Louis I. Kahn, "Silence and Light," lecture, 1969', text: 'A great building must begin with the unmeasurable, must go through measurable means when it is being designed, and in the end must be unmeasurable.\nKahn spoke of two brothers who stand always at the threshold of the maker: Silence, which is the desire to be, to express; and Light, the giver of all presence.\nWhere they meet — at the threshold between silence and light — is where the work of art wishes to be made.' },
  { title: 'Architecture Aims at Eternity', source: 'Sir Christopher Wren, "Of Architecture," in Parentalia, 1750', text: 'Architecture has its political use, public buildings being the ornament of a country; it establishes a nation, draws people and commerce, makes the people love their native country.\nBeauty, firmness, and convenience are the principles; the two first depend upon geometrical reasons of optics and statics; the third only makes the variety.\nArchitecture aims at eternity, and is therefore the only thing incapable of modes and fashions in its principals.' },
  { title: 'Design Alone', source: 'after Leon Battista Alberti, On the Art of Building, c. 1450', text: 'It is the property and business of design to appoint to the edifice and all its parts their proper places, determinate number, just proportion, and beautiful order, so that the whole form of the building may depend upon the design alone.\nNor has design anything that makes it inseparable from matter; the same design is preserved in numberless buildings of the same form, though built of very different materials.\nWhen you have laid out and adjusted this design in your mind, the whole work is already made.' },
  { title: 'The Reason of the Whole', source: 'after Andrea Palladio (trans. Ware), The Four Books of Architecture, 1570', text: 'Beauty will result from the beautiful form, and from the correspondence of the whole to the parts, of the parts amongst themselves, and of these again to the whole; so that the structure may appear an entire and complete body, wherein each member agrees with the other, and all are necessary for what is intended.\nWe ought to have regard to that which nature herself teaches us, taking her constantly for our guide.' },
  { title: 'We Cannot Remember Without Her', source: 'John Ruskin, The Seven Lamps of Architecture, "The Lamp of Memory," 1849', text: 'We may live without architecture, and worship without her, but we cannot remember without her.\nHow cold is all history, how lifeless all imagery, compared to that which the living nation writes, and the uncorrupted marble bears!\nThere are but two strong conquerors of the forgetfulness of men, Poetry and Architecture; and the latter in some sort includes the former, and is mightier in its reality.' },
  { title: 'Greatness of Dimension', source: 'Edmund Burke, A Philosophical Enquiry, 1757', text: 'Greatness of dimension is a powerful cause of the sublime.\nWhatever is fitted in any sort to excite the ideas of pain and danger, whatever is terrible, or operates in a manner analogous to terror, is a source of the sublime — that is, it is productive of the strongest emotion which the mind is capable of feeling.\nThe mind is hurried out of itself by a crowd of great and confused images, which affect because they are crowded and confused.' },
  { title: 'The thing signified, and its significance', source: 'Vitruvius, De Architectura, Book I, ch. 1 (Morgan trans.)', text: 'In all matters, but particularly in architecture, there are these two points: the thing signified, and that which gives it its significance. That which is signified is the subject of which we may be speaking; and that which gives significance is a demonstration on scientific principles.\n\nIt appears, then, that one who professes himself an architect should be well versed in both directions. He ought, therefore, to be both naturally gifted and amenable to instruction. Neither natural ability without instruction nor instruction without natural ability can make the perfect artist.' },
  { title: 'The proportions of the body and the temple', source: 'Vitruvius, De Architectura, Book III, ch. 1 (Morgan trans.)', text: 'The design of a temple depends on symmetry, the principles of which must be most carefully observed by the architect. They are due to proportion. Proportion is a correspondence among the measures of the members of an entire work, and of the whole to a certain part selected as standard.\n\nFor the human body is so designed by nature that the face, from the chin to the top of the forehead and the lowest roots of the hair, is a tenth part of the whole height. Without symmetry and proportion there can be no principles in the design of any temple; that is, if there is no precise relation between its members, as in the case of those of a well-shaped man.' },
  { title: 'The navel, the circle, and the square', source: 'Vitruvius, De Architectura, Book III, ch. 1 (Morgan trans.)', text: 'In the human body the central point is naturally the navel. For if a man be placed flat on his back, with his hands and feet extended, and a pair of compasses centred at his navel, the fingers and toes of his two hands and feet will touch the circumference of a circle described therefrom.\n\nAnd just as the human body yields a circular outline, so too a square figure may be found from it. For if we measure the distance from the soles of the feet to the top of the head, and then apply that measure to the outstretched arms, the breadth will be found to be the same as the height, as in the case of plane surfaces which are perfectly square.' },
  { title: 'The six fundamental principles', source: 'Vitruvius, De Architectura, Book I, ch. 2 (Morgan trans.)', text: 'Architecture depends on Order, Arrangement, Eurythmy, Symmetry, Propriety, and Economy.\n\nOrder gives due measure to the members of a work considered separately, and symmetrical agreement to the proportions of the whole. Arrangement includes the putting of things in their proper places and the elegance of effect which is due to adjustments appropriate to the character of the work.\n\nEurythmy is beauty and fitness in the adjustments of the members. This is found when the members of a work are of a height suited to their breadth, of a breadth suited to their length, and, in a word, when they all correspond symmetrically.' },
  { title: 'The first hut', source: 'Marc-Antoine Laugier, An Essay on Architecture, 1753 (1755 English trans.)', text: 'Near to a gentle stream man perceives a green turf; its fresh greenness pleases his eyes, and he approaches. But the sun\'s heat which scorches him obliges him to seek a shade, and a neighbouring wood offers him its cool retreat. Then a thousand vapours rise, thick clouds obscure the air, and a frightful rain pours down upon this delightful forest.\n\nSome branches broken down in the forest are the proper materials for his design. He chooses four of the strongest, which he raises perpendicularly, and disposes into a square. Above he lays four others across, and upon these he raises some that incline from both sides, and meet in a point. This kind of roof he covers with leaves so close that neither the sun nor the rain can penetrate.' },
  { title: 'The cabin is the model of all', source: 'Marc-Antoine Laugier, An Essay on Architecture, 1753 (1755 English trans.)', text: 'The little rustic cabin that I have just described is the model upon which all the magnificences of architecture have been imagined. It is by coming near in the execution to the simplicity of this first model that we avoid all essential defects and lay hold on true perfection.\n\nThe upright pieces of wood raised perpendicularly give us the idea of columns. The horizontal pieces that lie upon them afford us the idea of entablatures. And the inclining pieces that form the roof give us the idea of pediments. This is what all the masters of the art have acknowledged.' },
  { title: 'The imperfection of the workman', source: 'John Ruskin, "The Nature of Gothic", The Stones of Venice, 1853', text: 'No good work whatever can be perfect, and the demand for perfection is always a sign of a misunderstanding of the ends of art.\n\nIn all things that live there are certain irregularities and deficiencies which are not only signs of life, but sources of beauty. No human face is exactly the same in its lines on each side, no leaf perfect in its lobes, no branch in its symmetry. All admit irregularity as they imply change; and to banish imperfection is to destroy expression, to check exertion, to paralyze vitality. All things are literally better, lovelier, and more beloved for the imperfections which have been divinely appointed.' },
  { title: 'General principles of ornament', source: 'Owen Jones, The Grammar of Ornament, 1856', text: 'All ornament should be based upon a geometrical construction. Beauty of form is produced by lines growing out one from the other in gradual undulations: there are no excrescences; nothing could be removed and leave the design equally good or better.\n\nFlowers or other natural objects should not be used as ornaments, but conventional representations founded upon them, sufficiently suggestive to convey the intended image to the mind, without destroying the unity of the object they are employed to decorate.\n\nThat which is beautiful is true; that which is true must be beautiful.' },
  { title: 'The three parts of the tall building', source: 'Louis H. Sullivan, "The Tall Office Building Artistically Considered", 1896', text: 'Does this not readily, clearly, and conclusively show that the lower one or two stories will take on a special character suited to the special needs; that the tiers of typical offices, having the same unchanging function, shall continue in the same unchanging form; and that as to the attic, specific and conclusive as it is in its very nature, its function shall equally be so in force, in significance, in continuity, in conclusiveness of outward expression?\n\nFrom this results, naturally, spontaneously, unwittingly, a three-part division, not from any theory, symbol, or fancied logic.' },
  { title: 'The plan is the generator', source: 'Le Corbusier, Towards a New Architecture, 1923 (Etchells trans.)', text: 'The Plan is the generator. Without a plan, you have lack of order, and wilfulness. The Plan holds in itself the essence of sensation.\n\nThe Plan proceeds from within to without; the exterior is the result of an interior. The "styles" are a lie. Style is a unity of principle animating all the work of an epoch, the result of a state of mind which has its own special character.' },
  { title: 'The engineer and the architect', source: 'Le Corbusier, Towards a New Architecture, 1923 (Etchells trans.)', text: 'The Engineer\'s Aesthetic and Architecture are two things that march together and follow one from the other: the one being now at its full height, the other in an unhappy state of retrogression.\n\nThe Engineer, inspired by the law of Economy and governed by mathematical calculation, puts us in accord with universal law. He achieves harmony.' },
  { title: 'Greatness of dimension', source: 'Edmund Burke, A Philosophical Enquiry into the Sublime and Beautiful, 1757', text: 'Greatness of dimension is a powerful cause of the sublime. This is too evident, and the observation too common, to need any illustration; it is not so common to consider in what ways greatness of dimension, vastness of extent or quantity, has the most striking effect.\n\nFor certainly there are ways and modes wherein the same quantity of extension shall produce greater effects than it is found to do in others. Extension is either in length, height, or depth. Of these the length strikes least; a hundred yards of even ground will never work such an effect as a tower a hundred yards high, or a rock or mountain of that altitude.' },
  { title: 'The deception of the eye', source: 'Vitruvius, De Architectura, Book VI, ch. 2 (Morgan trans.)', text: 'There is nothing to which an architect should devote more thought than to the exact proportions of his building with reference to a certain part selected as the standard.\n\nSince, therefore, the reality may have a false appearance, and since things are sometimes represented by the eyes as other than they are, I think it certain that diminutions or additions should be made to suit the nature or needs of the site, but in such fashion that the buildings lose nothing thereby.' },
  { title: 'The centre was the human body', source: 'Geoffrey Scott, The Architecture of Humanism, 1914', text: 'The centre of that architecture was the human body; its method, to transcribe in stone the body\'s favourable states; and the moods of the spirit took visible shape along its borders, power and laughter, strength and terror and calm.\n\nThe tendency to project the image of our functions into concrete forms is the basis, for architecture, of creative design.' },
];

window.WORDS = [
  { word: 'entablature', lang: 'Italian / Latin', root: 'intavolatura, from tabula (board)', meaning: 'the whole horizontal band a colonnade carries — architrave, frieze and cornice together', english: 'Above the columns on any classical bank, church or town hall: the layered horizontal top before the roof.' },
  { word: 'pediment', lang: 'uncertain; perhaps from "pyramid"', root: 'English, 16th c.', meaning: 'the low triangular gable crowning a temple front, portico or window', english: 'The triangle over a grand doorway or above the columns of a temple-fronted building.' },
  { word: 'architrave', lang: 'Italian / Greek', root: 'archi- (chief) + trabs (beam)', meaning: 'the lowest band of the entablature — the main beam resting directly on the capitals', english: 'The plain flat band immediately above a row of columns; also the moulded frame around a door or window.' },
  { word: 'pilaster', lang: 'Italian', root: 'pilastro, from pila (pillar)', meaning: 'a flattened column set against a wall — the order in relief rather than in the round', english: 'On many façades: shallow "columns" that are really part of the wall, framing windows and corners.' },
  { word: 'frieze', lang: 'French / Latin', root: 'frise, perhaps from Phrygia', meaning: 'the middle band of the entablature, often carved with figures, or plain', english: 'The band between the architrave and the cornice — the Parthenon frieze is the most famous example.' },
  { word: 'rustication', lang: 'Latin', root: 'rusticus (of the country, rough)', meaning: 'masonry cut with deep joints and a rough face, to give a base weight and strength', english: 'The heavy, grooved stonework often used on the ground floor of palaces and grand houses.' },
  { word: 'portico', lang: 'Italian / Latin', root: 'porticus (porch)', meaning: 'a roofed porch of columns forming the entrance to a building', english: 'The columned porch you climb the steps into — the front of a temple, a church, or a country house.' },
  { word: 'dentil', lang: 'Latin', root: 'dens, dentis (tooth)', meaning: 'a small square block, repeated in a row under a cornice like a set of teeth', english: 'The little repeating blocks beneath the top moulding of a classical cornice — look up and count them.' },
  { word: 'cornice', lang: 'Italian, from Latin/Greek', root: 'Latin coronis, Greek koronis (curved line, flourish)', meaning: 'the projecting top band of the entablature that crowns and casts shadow', english: 'The moulding that juts out at the very top of a classical wall, throwing a shadow line and shedding rain.' },
  { word: 'tympanum', lang: 'Latin, from Greek', root: 'Greek tympanon (drum)', meaning: 'the flat recessed face enclosed within a pediment or arch', english: 'The triangular panel inside a pediment — often filled with sculpture, as on the Parthenon or a courthouse.' },
  { word: 'entasis', lang: 'Greek', root: 'entasis (a stretching, tension)', meaning: 'the slight outward swelling of a column shaft to counter an optical illusion', english: 'Sight up a Greek column: the shaft bulges very gently rather than tapering in a dead-straight cone.' },
  { word: 'volute', lang: 'French, from Latin', root: 'Latin voluta (scroll), from volvere (to roll, turn)', meaning: 'the spiral scroll that forms the Ionic capital', english: 'The pair of ram\'s-horn spirals curling at the top of an Ionic column, like a rolled-up scroll.' },
  { word: 'acanthus', lang: 'Latin, from Greek', root: 'Greek akanthos, from akantha (thorn, spine)', meaning: 'a spiny Mediterranean plant whose leaves model the Corinthian capital', english: 'The deeply cut, curling leaves wrapping the top of a Corinthian column are stylised acanthus foliage.' },
  { word: 'echinus', lang: 'Latin, from Greek', root: 'Greek echinos (sea-urchin, hedgehog)', meaning: 'the rounded cushion-moulding beneath the square top of a Doric capital', english: 'On a Doric column, the plain convex ring that swells out just under the flat slab at the very top.' },
  { word: 'abacus', lang: 'Latin, from Greek', root: 'Greek abax (slab, board, tablet)', meaning: 'the flat square slab at the top of a capital, taking the load of the beam above', english: 'The plain flat block sitting on top of any capital, the last step before the beam it carries.' },
  { word: 'metope', lang: 'Latin, from Greek', root: 'Greek metope, from meta (between) + ope (opening)', meaning: 'the square panel between two triglyphs in a Doric frieze', english: 'In a Doric frieze, the plain or carved square panels alternating with the grooved blocks.' },
  { word: 'triglyph', lang: 'Latin, from Greek', root: 'Greek tri- (three) + glyphe (carving, groove)', meaning: 'the grooved block in a Doric frieze, memory of a timber beam-end', english: 'The upright block cut with vertical grooves, repeating along a Doric frieze between the panels.' },
  { word: 'modillion', lang: 'French, from Italian/Latin', root: 'Italian modiglione, from Latin modulus (small measure)', meaning: 'a scroll-shaped bracket set in rows beneath a Corinthian cornice', english: 'The little S-shaped brackets marching in a row under a rich cornice, seeming to hold it out.' },
  { word: 'rotunda', lang: 'Italian, from Latin', root: 'Latin rotundus (round), from rota (wheel)', meaning: 'a round building or round domed hall', english: 'A circular room under a dome — like the centre of the Pantheon or a domed capitol hall.' },
  { word: 'coffer', lang: 'French, from Latin/Greek', root: 'Greek kophinos (basket) via Latin cophinus (chest)', meaning: 'a sunken square or polygonal panel in a ceiling or vault', english: 'The grid of recessed panels sunk into a dome or ceiling, like the honeycomb inside the Pantheon\'s dome.' },
  { word: 'keystone', lang: 'English', root: 'key + stone — the locking stone', meaning: 'the central wedge at the top of an arch that locks the others in place', english: 'The single stone at the very crown of an arch, often larger or carved, holding the whole arch together.' },
  { word: 'voussoir', lang: 'French, from Latin', root: 'from Latin volvere (to roll, turn)', meaning: 'any one of the wedge-shaped stones forming an arch', english: 'Each tapered block fanning around an arch, from the springing at the sides up to the keystone.' },
  { word: 'baluster', lang: 'Italian, from Greek', root: 'balaustro, from balaustra (wild-pomegranate flower), for its shape', meaning: 'one of the small vase-shaped posts supporting a rail', english: 'The little turned posts holding up a stair rail or terrace parapet — look for the swelling pomegranate-bud profile.' },
  { word: 'balustrade', lang: 'French, from Italian', root: 'from balaustro (baluster)', meaning: 'a whole row of balusters carrying a coping rail', english: 'The low railing of little posts running along a roofline, balcony or grand staircase.' },
  { word: 'cupola', lang: 'Italian, from Latin', root: 'cupula (little cask), diminutive of cupa (cask, tub)', meaning: 'a small dome crowning a roof, tower or larger dome', english: 'The little rounded dome or turret sitting on top of a courthouse, church or grand roof.' },
  { word: 'lantern', lang: 'Latin, from Greek', root: 'lanterna, from Greek lampter (torch)', meaning: 'a windowed turret set on a dome or roof to admit light', english: 'The little glazed drum on top of a dome — the ring of light at the very crown of St Paul\'s or a capitol.' },
  { word: 'drum', lang: 'English', root: 'from the shape of the musical drum', meaning: 'the cylindrical wall that carries a dome; also each round block of a column shaft', english: 'The tall circular wall, often ringed with windows, lifting a dome up into the light above the roofs.' },
  { word: 'pendentive', lang: 'French, from Latin', root: 'pendentif, from pendere (to hang)', meaning: 'the curved triangular surface that carries a round dome over a square space', english: 'The concave triangles in the upper corners of a domed room, gathering the circle of the dome down onto four piers.' },
  { word: 'spandrel', lang: 'English, from Old French', root: 'from espandre (to spread out)', meaning: 'the roughly triangular space between the curve of an arch and the rectangle around it', english: 'The near-triangular panel beside the top of an arch, often carved with a figure or a roundel.' },
  { word: 'impost', lang: 'Italian/Latin', root: 'imposta, from imponere (to lay upon)', meaning: 'the block or moulding from which an arch springs', english: 'The bracket-like moulding where an arch leaves the wall or pier and begins to curve.' },
  { word: 'quoin', lang: 'French, from Latin', root: 'coin (corner, wedge), from cuneus (wedge)', meaning: 'the dressed cornerstones that reinforce and mark the angle of a wall', english: 'The larger, often rusticated stones stacked at the corners of a building, framing its edges.' },
  { word: 'corbel', lang: 'French, from Latin', root: 'corbel (little raven), from corvus (raven), for the beak-like shape', meaning: 'a block of stone projecting from a wall to carry a beam or cornice', english: 'A short bracket jutting from a wall to hold up a shelf, balcony or roof-beam above.' },
  { word: 'console', lang: 'French', root: 'perhaps from consolider (to strengthen)', meaning: 'an S-shaped scroll bracket supporting a cornice, shelf or bust', english: 'The curling scroll-brackets flanking a grand doorway or holding a stone shelf beneath a window.' },
  { word: 'cartouche', lang: 'French, from Italian', root: 'cartoccio (paper cornet), from Latin charta (paper)', meaning: 'an ornamental panel shaped like a scroll or shield, often bearing an inscription', english: 'The scroll-edged tablet set over a doorway or on a frieze, framing a date, name or coat of arms.' },
  { word: 'festoon', lang: 'French, from Italian', root: 'feston, from festa (feast, festival garland)', meaning: 'a carved garland of flowers, fruit and leaves hung in a slack curve', english: 'The swag of sculpted fruit and flowers looping between two points along a frieze or above a window.' },
  { word: 'guilloche', lang: 'French', root: 'perhaps from a personal name, Guillaume', meaning: 'a running ornament of interlaced curving bands forming a plait', english: 'The ribbon of interwoven circles or plaits running as a border along a moulding or frieze.' },
  { word: 'fret', lang: 'English / Greek', root: 'also called the meander, from the winding river Maiandros', meaning: 'an angular key-pattern band of continuous right-angled lines', english: 'The "Greek key" border of squared, interlocking lines — on friezes, floors and the edges of panels.' },
  { word: 'patera', lang: 'Latin', root: 'patera (a shallow libation dish)', meaning: 'a small flat round ornament, like a disc or rosette', english: 'The little carved discs or flower-rosettes spaced along a frieze or set into a ceiling.' },
  { word: 'bucranium', lang: 'Latin, from Greek', root: 'bous (ox) + kranion (skull)', meaning: 'a carved ox-skull ornament, a memory of ancient sacrifice', english: 'The garlanded ox-skulls alternating with dishes along a classical frieze, especially in the Doric.' },
  { word: 'stylobate', lang: 'Greek', root: 'stylos (column) + bates (that on which one treads)', meaning: 'the top step of the platform on which a colonnade stands', english: 'The continuous stone floor a row of temple columns rises from — the top of the stepped base.' },
  { word: 'peristyle', lang: 'Greek', root: 'peri (around) + stylos (column)', meaning: 'a continuous colonnade surrounding a temple or an inner court', english: 'The ring of columns wrapping right around a temple, or the columned walk enclosing a courtyard.' },
  { word: 'cella', lang: 'Latin', root: 'cella (chamber, storeroom); the Greek is naos', meaning: 'the enclosed inner room of a temple, housing the god\'s image', english: 'The solid windowless heart of a temple, inside the columns — where the statue of the god once stood.' },
  { word: 'oculus', lang: 'Latin', root: 'oculus (eye)', meaning: 'a circular opening at the crown of a dome, or a round window', english: 'The great round eye open to the sky at the top of the Pantheon\'s dome — or any small circular window.' },
  { word: 'lunette', lang: 'French', root: 'lunette (little moon), from lune (moon)', meaning: 'a half-moon-shaped panel or window over a door or within a vault', english: 'The semicircular panel above a doorway or window, often filled with a painting or a fanlight.' },
  { word: 'loggia', lang: 'Italian', root: 'related to lodge / French loge', meaning: 'a gallery or room open on one side through a row of columns or arches', english: 'The shaded, open-sided arcade along the front or side of a palazzo, looking onto square or garden.' },
  { word: 'aedicule', lang: 'Latin', root: 'aedicula (little building, shrine), diminutive of aedes (temple)', meaning: 'a niche or opening framed by two columns carrying a pediment', english: 'A window or statue-niche dressed as a tiny temple front — two little columns and a gable — set against the wall.' },
  { word: 'mutule', lang: 'Latin', root: 'mutulus (a projecting block)', meaning: 'the flat sloping slab above each triglyph, under the Doric cornice', english: 'The square projecting blocks, studded with little pegs, spaced along the underside of a Doric cornice.' },
  { word: 'guttae', lang: 'Latin', root: 'guttae (drops)', meaning: 'the small peg-like "drops" hung beneath the triglyphs and mutules of the Doric', english: 'The rows of little cones or pegs under a Doric frieze — stone memories of the pegs of the first timber temples.' },
  { word: 'torus', lang: 'Latin, from Greek', root: 'torus (a swelling, a cushion or bulge)', meaning: 'the large convex half-round moulding at the foot of a column base', english: 'The fat, rounded ring bulging out at the very bottom of a column base, like a cushion under the shaft.' },
  { word: 'ovolo', lang: 'Italian', root: 'ovolo (little egg), from Latin ovum (egg)', meaning: 'a convex quarter-round moulding, often carved with egg-and-dart', english: 'The rounded moulding beneath a capital or cornice, usually cut with the alternating egg-and-dart pattern.' },
  { word: 'plinth', lang: 'Greek, via Latin', root: 'plinthos (a brick or squared stone)', meaning: 'the square block at the foot of a column base, or the projecting base of a wall', english: 'The plain square slab a column or a statue stands on, and the low band around the foot of a building.' },
];
